  [458285] = { nil, "Cura $N1 salute ogni $N2 secondi.", nil, 0x6ae8a0f4, "mu" },
  [458287] = { "La tua Consacrazione ora cura anche i membri del gruppo nella sua area del $N1% del valore dei danni di Consacrazione.", nil, 0xd606e177, nil, "um" },
  [458312] = { "Riduce del $N1% tutti i danni subiti per $D1. Una volta ricevuta la protezione, non puoi più essere bersaglio di ⟦Divine Shield=Scudo Divino⟧, ⟦Divine Protection=Protezione Divina⟧ o ⟦Blessing of Protection=Benedizione della Protezione⟧ per $D2.", "Danni subiti ridotti del $N1%.", 0x4f4c8473, 0xa4f10210, "uu" },
  [458318] = { "Ora puoi agire durante ⟦Divine Protection=Protezione Divina⟧ e la sua durata aumenta del $N1%, ma invece di renderti immune riduce solo del $N2% i danni che subisci. Inoltre, attivare ⟦Holy Shield=Scudo Benedetto⟧ ti fornisce anche $N3 potenza d'attacco per ogni punto della tua abilità in difesa oltre $N4, per $D1.", nil, 0xef5783e0, nil, "um" },
  [458371] = { "Riduce del $N1% tutti i danni subiti per $D1. Una volta ricevuta la protezione, non puoi più essere bersaglio di ⟦Divine Shield=Scudo Divino⟧, ⟦Divine Protection=Protezione Divina⟧ o ⟦Blessing of Protection=Benedizione della Protezione⟧ per $D2.", "Danni subiti ridotti del $N1%.", 0x4f4c8473, 0xa4f10210, "uu" },
  [458393] = { "Morso della Mangusta ora ha una probabilità del $N1% di attivarsi a ogni tuo attacco in mischia, e del $N2% quando un nemico schiva. Questa probabilità si accumula, aumentando del $N3% a ogni attacco successivo se non si azzera. Morso della Mangusta infligge anche danni aggiuntivi pari al $N4% della tua potenza d'attacco.", nil, 0x31863f78, nil, "um" },
  [458403] = { nil, "Probabilità di colpire con tutti gli attacchi aumentata del $N1%.", nil, 0x36a319d2, "mu" },
  [458407] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
  [458436] = { "Un assalto feroce che infligge il $N1% dei danni dell'arma e fa sanguinare il bersaglio, infliggendo $N2 danni fisici in $D1.", "$N1 danni da sanguinamento ogni $N2 s.", 0xa0da7bd7, 0xd7a9220a, "uu" },
  [458454] = { "Offri l'eco.", nil, 0x10968b43, nil, "um" },
  [458479] = { "Sostituisce la tua abilità ⟦Wyvern Sting=Morso della Viverna⟧ con Wyvern Strike, un assalto feroce che infligge il $N1% dei danni dell'arma e fa sanguinare il bersaglio, infliggendo danni nel tempo.\n\nWyvern Strike richiede il talento ⟦Wyvern Sting=Morso della Viverna⟧ e sostituisce le abilità ⟦Wyvern Sting=Morso della Viverna⟧ del libro degli incantesimi Sopravvivenza.", nil, 0xdd66b74c, nil, "um" },
  [458481] = { "Un assalto feroce che infligge il $N1% dei danni dell'arma e fa sanguinare il bersaglio, infliggendo $N2 danni fisici in $D1.", "$N1 danni da sanguinamento ogni $N2 s.", 0xa0da7bd7, 0xd7a9220a, "uu" },
  [458482] = { "Un assalto feroce che infligge il $N1% dei danni dell'arma e fa sanguinare il bersaglio, infliggendo $N2 danni fisici in $D1.", "$N1 danni da sanguinamento ogni $N2 s.", 0xa0da7bd7, 0xd7a9220a, "uu" },
  [458590] = { nil, "La fine di un'epoca è vicina!", nil, 0xa1468809, "mu" },
  [458819] = { "Infligge danni da fuoco a un nemico.", nil, 0x6c371710, nil, "um" },
  [458820] = { nil, "Il bersaglio subisce $N1 danni da natura ogni $N2 s e il $N3% di danni da arcano, da fuoco, da gelo, da natura e da ombra in più.", nil, 0x4290b92c, "mu" },
  [458821] = { "Ricopre un'arma con un veleno che dura $N1 min. Ogni colpo ha una probabilità del $N2% di avvelenare il nemico, infliggendo $N3 danni da natura in $D1 e facendogli subire il $N5% di danni da arcano, da fuoco, da gelo, da natura e da ombra in più. Si accumula fino a $N6 volte su un singolo bersaglio.\n\nOccult Poison conta come ⟦Deadly Poison=Veleno Mortale⟧ e beneficia di tutti i talenti e gli effetti attivati o modificati da ⟦Deadly Poison=Veleno Mortale⟧.", nil, 0xac6b5ded, nil, "um" },
  [458822] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, infliggendo $N3 danni da natura in $D1 e facendogli subire il $N5% di danni da arcano, da fuoco, da gelo, da natura e da ombra in più. Si accumula fino a $N6 volte su un singolo bersaglio.\n\nOccult Poison conta come ⟦Deadly Poison=Veleno Mortale⟧ e beneficia di tutti i talenti e gli effetti attivati o modificati da ⟦Deadly Poison=Veleno Mortale⟧.", nil, 0xdba5bb61, nil, "um" },
  [458841] = { nil, "I Seguaci di Idraxis offrono il massimo sollievo, riducendo al minimo il calore nel ⟦Molten Core=Nucleo Ardente⟧.", nil, 0x19674aed, "mu" },
