  [458843] = { nil, "I Seguaci di Idraxis non offrono alcun sollievo. Il ⟦Molten Core=Nucleo Ardente⟧ è al massimo della sua intensità.", nil, 0x17d3b2a6, "mu" },
  [458856] = { "Cura un bersaglio amico di $N1. Il $N2% di qualsiasi cura in eccesso sul bersaglio viene convertito in uno scudo assorbente che dura $D1. Più lanci di Luce Divina non accumulano questo scudo.\n\nLuce Divina beneficia di tutti i talenti e gli effetti che si attivano da ⟦Holy Light=Luce Sacra⟧ o la modificano.", nil, 0x5eb11dfb, nil, "um" },
